[850] = {id=850,name="Kolkar Leaders",level=5,requiredLevel=5,faction="horde",expansion=6,zoneID=17,mapID=10,description="The centaurs have plagued the tauren for years. And recently, the Kolkar centaurs of the Barrens have grown into a real threat. Normally they were disorganized in these lands, but new leaders have risen among them. Rallying them. To preserve our holdings here, these centaur leaders must be destroyed. Bring me the head of Barak Kodobane. He camps west of these Forgotten Pools. Defeat him, then return to me.",starts={{npcID=3389,x=0.378,y=0.552,mapID=10},{npcID=34841,x=0.38,y=0.464,mapID=10}},ends={{npcID=3389,x=0.378,y=0.552,mapID=10},{npcID=34841,x=0.38,y=0.464,mapID=10}},coords={x=0.378,y=0.552,source="quest_giver",mapID=10},questType="standard"},
[10729] = {id=10729,name="Path of the Violet Mage",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=41,mapID=42,starts={{npcID=18253,x=0.472,y=0.75,mapID=42}},ends={{npcID=18253,x=0.472,y=0.75,mapID=42}},coords={x=0.472,y=0.75,source="quest_giver",mapID=42},questType="standard"},
