[10732] = {id=10732,name="Path of the Violet Protector",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=41,mapID=42,starts={{npcID=18253,x=0.472,y=0.75,mapID=42}},ends={{npcID=18253,x=0.472,y=0.75,mapID=42}},coords={x=0.472,y=0.75,source="quest_giver",mapID=42},questType="standard"},
[14407] = {id=14407,name="Azshara Blues",level=5,requiredLevel=5,faction="horde",expansion=6,zoneID=16,mapID=76,description="Hey! I'm glad I caught you. I come on behalf of my master, Kalec . He requires your aid. Find him under the bridge in the slums as soon as you can!",starts={{npcID=36999,x=0.594,y=0.506,mapID=76}},ends={{npcID=35867,x=0.554,y=0.52,mapID=76}},coords={x=0.594,y=0.506,source="quest_giver",mapID=76},questType="standard"},
[14464] = {id=14464,name="Lightning Strike Assassination",level=5,requiredLevel=5,faction="horde",expansion=6,zoneID=16,mapID=76,description="The base of the tower is patrolled by the Captain's elite guards. So here's what we're going to do: we're going to grapple straight up to the top, slice-and-dice the VIPs, and bail out using my portable low-altitude parachute . I'll rig the tower to explode behind us. You be sure to grab Captain Grunwald's head for Chawg . Got it? Do NOT accept this mission unless you are prepared for UNMITIGATED BADASSERY. Is that clear?",starts={{npcID=36729,x=0.12,y=0.682,mapID=76}},ends={{npcID=36730,x=0.14,y=0.648,mapID=76}},coords={x=0.12,y=0.682,source="quest_giver",mapID=76},questType="standard"},
[24455] = {id=24455,name="Rapid Deployment",level=5,requiredLevel=5,faction="horde",expansion=6,zoneID=16,mapID=76,description="You will be reporting for active duty immediately. Captain Desoto is overseeing deployment just down the ramp at the rocket launch station. Make us rich, soldier. Dismissed!",starts={{npcID=36749,x=0.294,y=0.576,mapID=76}},ends={{npcID=36956,x=0.58,y=0.522,mapID=76}},coords={x=0.294,y=0.576,source="quest_giver",mapID=76},questType="standard"},
[24740] = {id=24740,name="Volcanic Activity",level=15,requiredLevel=15,faction="both",expansion=6,zoneID=490,mapID=78,description="Welcome. I'm Williden Marshal , and my sister and I run this expedition of explorers and scientists. You have a moment? I don't like the look of those elementals on that volcano, . We have too much equipment, too many notes... one crazed elemental could streak its way through our camp and do terrible, terrible damage. Show them that their new neighbors aren't to be trifled with. And bring back the ash that they leave behind... we might as well do a little science while we're at it.",starts={{npcID=9270,x=0.55,y=0.622,mapID=78}},ends={{npcID=9270,x=0.55,y=0.622,mapID=78}},coords={x=0.55,y=0.622,source="quest_giver",mapID=78},questType="standard"},
[24854] = {id=24854,name="Finding Stormclaw",level=15,requiredLevel=15,faction="both",expansion=6,zoneID=490,mapID=78,description="Zen'Aliri been studyin' the ways of the druid, . Hopefully one day, Zen'Aliri join the Druids of the Talon, and soar over this crater as a storm crow. But for now, my mentor says I stay here and wait. So Zen'Aliri waits. I know another druid who might be able to use your help. His name is Garl Stormclaw , and he's somewhere to the east of here, studying reagents. Maybe you go talk to him?",starts={{npcID=38269,x=0.556,y=0.606,mapID=78}},ends={{npcID=38274,x=0.71,y=0.766,mapID=78}},coords={x=0.556,y=0.606,source="quest_giver",mapID=78},questType="standard"},
[25377] = {id=25377,name="The Horde's Hoard",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=4815,mapID=201,description="It is unclear what manner of creature scrawled the seemingly random markings on this piece of parchment, but upon close inspection, some of the obscure shapes begin to look like landmarks. Scanning the sea floor, you think you recognize a few points of reference, one being a nearby sunken ship. If your guess is correct, there appears to be treasure of some kind near the wreck. You cannot help but wonder what the scaly, serpentine figure on the map might represent....",ends={{npcID=202759,x=0.579,y=0.352,mapID=201}},questType="standard"},
[25419] = {id=25419,name="Lady La-La's Medallion",level=30,requiredLevel=30,faction="none",expansion=6,zoneID=4815,mapID=201,description="Dozens of crude gold links make up this heavy chain. Dangling from the center link is an opalescent fragment of what must have once been a large shell-shaped medallion. You wonder if the other fragments might be nearby, and if the medallion might be reassembled into its original state.",questType="standard"},
[25467] = {id=25467,name="Kliklak's Craw",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=4815,mapID=201,description="You are pleasantly surprised to find that after being mangled and masticated by a sea crab, this map is still quite legible. It clearly indicates that a footlocker was buried in the Kelp'thar Forest behind a gigantic mollusk. A well-drawn sketch on the back of the map shows that the owner, along with his key, was eaten by an overgrown crustacean named Kliklak.",ends={{npcID=202859,x=0.466,y=0.475,mapID=201}},questType="standard"},
[25812] = {id=25812,name="Spelunking",level=30,requiredLevel=30,faction="alliance",expansion=6,zoneID=4815,mapID=201,description="Hurry, ! Make your way to that cavern at once. We shall go behind you to ensure that you are not followed.",starts={{npcID=40105,x=0.462,y=0.468,mapID=201}},ends={{npcID=41324,x=0.638,y=0.598,mapID=201}},coords={x=0.462,y=0.468,source="quest_giver",mapID=201},questType="standard"},
[26000] = {id=26000,name="Spelunking",level=30,requiredLevel=30,faction="horde",expansion=6,zoneID=4815,mapID=201,description="Hurry, ! Make your way to that cavern at once. We shall go behind you to ensure that you are not followed.",starts={{npcID=40105,x=0.462,y=0.468,mapID=201}},ends={{npcID=41863,x=0.638,y=0.598,mapID=201}},coords={x=0.462,y=0.468,source="quest_giver",mapID=201},questType="standard"},
[26194] = {id=26194,name="Defending the Rift",level=30,requiredLevel=30,faction="horde",expansion=6,zoneID=5145,mapID=204,description="The whispers of the elements are crowding my thoughts, ... The Throne of Tides is under siege! I cannot stand idly by while the naga threaten Neptulon's realm. We must find a way to join forces with him. Nazgrim will escort me to the depths where I can commune directly with Neptulon. I must ask you to take a more violent path. Keep the enemy forces distracted until I arrive safely at entrance to the Throne of Tides. May the spirits see us through, .",starts={{npcID=41600,x=0.426,y=0.378,mapID=204}},ends={{npcID=44540,x=0.696,y=0.344,mapID=204}},coords={x=0.426,y=0.378,source="quest_giver",mapID=204},questType="standard"},
[26297] = {id=26297,name="The Dawning of a New Day",level=5,requiredLevel=5,faction="alliance",expansion=6,zoneID=40,mapID=52,description="It looks like the meeting the shadowy figure spoke of is starting soon. The homeless are starting to mobilize. I need you to attend the rally and gather information, . Go to the center of Moonbrook and listen in on the rally. Return to me with whatever you find out.",starts={{npcID=42425,x=0.42,y=0.64,mapID=52}},ends={{npcID=42425,x=0.42,y=0.64,mapID=52}},coords={x=0.42,y=0.64,source="quest_giver",mapID=52},questType="standard"},
[27357] = {id=27357,name="The Captive Bride",level=15,requiredLevel=15,faction="alliance",expansion=6,zoneID=400,mapID=64,description="Of course! Lakota Windsong ! Why didn't I think of this before? Arnak kidnapped Lakota years ago and tried to force her into being his bride. She managed to escape, but in the chaos of the recent attack on Freewind Post, he took her again. She has to be around here somewhere. She's become quite the mystic in recent years. I'm guessing she'll know what to do with these tauren artifacts.",ends={{npcID=45442,x=0.39,y=0.258,mapID=64}},questType="standard"},
[27358] = {id=27358,name="The Captive Bride",level=15,requiredLevel=15,faction="horde",expansion=6,zoneID=400,mapID=64,description="Lakota Windsong ! Why did I not think of this before? Arnak kidnapped Lakota years ago and tried to force her to be his bride. With help, she was able to escape, but in the chaos of the recent attack on Freewind Post, he took her again. She must be near. She has become quite the shaman in recent years. I am sure that she will understand the significance of the rattle, the writ, and the drums.",ends={{npcID=45442,x=0.39,y=0.258,mapID=64}},questType="standard"},
[29091] = {id=29091,name="Freedom Movement",level=5,requiredLevel=5,faction="none",expansion=6,zoneID=17,mapID=10,questType="standard"},
[37518] = {id=37518,name="The Haunted Halls",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,mapID=630,description="Now, what was it you wanted? You're here to see the Tidestone of Golganneth? Hah! Ho ho ha ha haa! Hooo my. No, only the academy's headmistress has the keys to that chamber, and she hasn't opened the door in... oh, I'd say about ten thousand years. You'd best be off to class, now. Go on, then! Into the west wing with you!",questType="standard"},
[37530] = {id=37530,name="Save Yourself",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,mapID=630,description="Of course I couldn't sit back and let them just cart you away. I will explain everything.",starts={{npcID=89009,x=0.578,y=0.434,mapID=630}},coords={x=0.578,y=0.434,source="quest_giver",mapID=630},questType="standard"},
[37729] = {id=37729,name="Pop Quiz: Advanced Rune Drawing",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,mapID=630,description="Still aching to get into the headmistress' study, eh? I suppose I can let you in... as long as you prove that you've been studying. Proper rune formation is essential when it comes to spellcasting. If you can draw a rune, you can cast a spell. I will provide outlines for you. You can simply use your feet to trace the runes.",questType="standard"},
[37857] = {id=37857,name="Runas Knows the Way",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,mapID=630,description="I wish to make it up to you for whatever I did that made you want to kill me. Hmm... your dragon complains about being weak. I know why. Runas can fix it, my friend. One of my kind, Ael'Yith, pulls ley energy from the very ground of Azsuna . I can take you to the location of his mana siphons. It's not too late to undo the harm the others have done. You've done well to trust me.",starts={{npcID=90383,x=0.538,y=0.168,mapID=630}},ends={{npcID=89978,x=0.534,y=0.162,mapID=630},{npcID=90569,x=0.534,y=0.164,mapID=630}},coords={x=0.538,y=0.168,source="quest_giver",mapID=630},questType="standard"},
[37908] = {id=37908,name="Inquisitor Ernstenbok",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7334,mapID=630,questType="standard"},
[38461] = {id=38461,name="Vignette: Guarms Mate (Fenri)",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7588,mapID=649,questType="standard"},
[38818] = {id=38818,name="The Final Judgment",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7588,mapID=649,description="In my fragmented state, I captured glimpses of a hero meting out justice to the corrupted mystics of Haustvald. I see now, this hero was you, . I know you seek my judgment, but my spirit is still fragmented. As we speak, Runeseer Faljar is calling upon dark, forbidden magics in an attempt to banish my spirit to Helheim. If he succeeds, your trial will be lost. My connection here is fading. Go, there is little time!",starts={{npcID=93234,x=0.714,y=0.424,mapID=634}},ends={{npcID=97319,x=0.652,y=0.472,mapID=649}},coords={x=0.714,y=0.424,source="quest_giver",mapID=649},questType="standard"},
