[38914] = {id=38914,name="Secrets of Highmountain",level=1,requiredLevel=1,faction="alliance",expansion=6,zoneID=7503,mapID=650,description="Now that you are familiar with our greatest hero, perhaps you are willing to assist me on a very dangerous endeavor. To this end I have sent word for one of your allies to join us. When you are ready, join us in my spirit lodge. It is up the elevators and across the southwestern most bridge.",questType="standard"},
