[39011] = {id=39011,name="Black Rook Invasion",level=10,requiredLevel=10,faction="none",expansion=6,zoneID=7558,mapID=641,description="Once, this area was peaceful and prosperous. Then we saw the first bad omens: strange ailments, spoiled crops, and the like. Now ghosts attack us from that castle across the river, and undead assassins slay our fishers so as to cut off the village's food supply. We're the last family living this close to the castle, but we daren't retreat: this river is the best route for fishers to bring their hauls in to town. Please, will you take the fight to these undead?",questType="standard"},
[39015] = {id=39015,name="Grumpy",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,mapID=641,starts={{npcID=92738,x=0.386,y=0.656,mapID=641}},ends={{npcID=92738,x=0.386,y=0.656,mapID=641}},coords={x=0.386,y=0.656,source="quest_giver",mapID=641},questType="standard"},
[39017] = {id=39017,name="Rise to the Occasion",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7543,mapID=646,description="The Lich King made a wise choice in giving you that weapon, . You've proven your strength and cunning on countless occasions and it is time that you have a position fitting for your accomplishments.",questType="standard"},
[39023] = {id=39023,name="Call of the Archmage",level=40,requiredLevel=40,faction="none",expansion=6,description="Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp. This will not take long.",questType="standard"},
