[39032] = {id=39032,name="A Summons from Saylanna",level=10,requiredLevel=10,faction="none",expansion=6,zoneID=7558,mapID=641,description="Sprites have always been mischievous creatures, but lately their mischief has turned to violence. One of the druids I call friend, Saylanna Riverbreeze, reports that they are assaulting the faerie dragon nesting grounds. The Lunarwing Shallows lie to the south. You will find Saylanna there.",questType="standard"},
