[39125] = {id=39125,name="Demon Destroyer",level=10,requiredLevel=10,faction="none",expansion=6,zoneID=7541,mapID=634,description="The demons spreading this corruption must be dealt with. Kill their generals and their plans will unravel. I have a gift for you. This horn was given to me by Odyn himself, use it to strike down all that stand in your way. The gods will surely smile upon you if you thwart the advances of Legion.",questType="standard"},
[39129] = {id=39129,name="Ill Tempered",level=40,requiredLevel=40,faction="none",expansion=6,zoneID=6723,mapID=534,questType="standard"},
[39130] = {id=39130,name="7.0 Val'sharah - River: Vignette: Purging the River - TRACKING - twh",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[39131] = {id=39131,name="Possessions of Power",level=5,requiredLevel=5,faction="none",expansion=6,description="Echoes of a thousand worlds swirl in the palm of your hand. Its true value lies in the eye of the beholder.",questType="standard"},
[39138] = {id=39138,name="March Forth and Conquer",level=1,requiredLevel=1,faction="both",expansion=6,description="You should make sure that we do not lose momentum, Highlord. There is still much to be done in Azsuna. We have a map of the island set up near the front of the sanctum. Meet me there and you can delegate your forces to handle important tasks in the area.",questType="standard"},
[39142] = {id=39142,name="Testing a Theory",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,mapID=630,description="Now that the Bloodstone has fed, I hope to use its power to bend the will of demons that would otherwise not be so easily controlled. Of course, this is all theory. I have never witnessed the direct effect of the Bloodstone 's power on a demon. This is where you come in. I have procured a few imps that should make suitable test subjects. Use the Bloodstone on them and report back to me with your findings.",starts={{npcID=105816,x=0.608,y=0.306,mapID=630}},ends={{npcID=105816,x=0.608,y=0.306,mapID=630}},coords={x=0.608,y=0.306,source="quest_giver",mapID=630},questType="standard"},
[39147] = {id=39147,name="6.2 Tanaan - PTR - Unlock Tanaan Debug",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=6723,mapID=534,questType="standard"},
[39151] = {id=39151,name="Forging the Artifact",level=1,requiredLevel=1,faction="both",expansion=6,description="We've certainly got our work cut out for us, but not to worry. There's nae weapon in existence that ye can't improve, legendary ones included! This anvil's only powerful enough to imbue your artifact once before we'll need something better, but that'll have to do fer now.",questType="standard"},
[39158] = {id=39158,name="Vignette: Rally the Wilds",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[39189] = {id=39189,name="Warchief's Command: Nagrand!",level=15,requiredLevel=15,faction="horde",expansion=6,zoneID=3518,mapID=107,description="We have lost contact with the druids of the Cenarion Thicket The Warchief has commanded any able bodies of the Horde to venture into Terokkar Forest and discover what has happened. The thicket can be found by heading northwest through Terokkar Forest from Zangarmarsh.",questType="standard"},
[39190] = {id=39190,name="DEPRECATED",level=1,requiredLevel=1,faction="both",expansion=6,description="The Knights of the Ebon Blade are ready. Place your hand upon the Orb of Command and Acherus will move to its new resting place. We await your orders, Highlord.",questType="standard"},
[39210] = {id=39210,name="The Magical Kingdom of Dalaran",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=2817,mapID=127,description="The Kirin Tor have moved their city here to Northrend. No longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest. They believe you to be ready for your journey to the city. Look for the teleportation crystal in Crystal Song Forest. When you arrive, seek out Archmage Celindra .",questType="standard"},
[39235] = {id=39235,name="Buba",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39276] = {id=39276,name="Strange Tools",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6720,mapID=525,description="We are well on our way to building our first ship, but unfortunately, I am not the orc for the job. I have no idea how to work with these human tools. Your shipwright, Yanas Seastrike , is going to take over from here on out. I will be here at the dry docks if you need anything from me.",starts={{npcID=94429,x=0.298,y=0.106,mapID=539},{npcID=94429,x=0.408,y=0.702,mapID=525}},ends={{npcID=95002,x=0.298,y=0.106,mapID=539}},coords={x=0.298,y=0.106,source="quest_giver",mapID=525},questType="standard"},
[39292] = {id=39292,name="Ashran Dominance",level=1,requiredLevel=1,faction="horde",expansion=6,zoneID=8485,mapID=588,description="The Alliance refuse to back down in Ashran . Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.",questType="standard"},
