[39329] = {id=39329,name="A Dormant Burner",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="I've heard that someone over in the engineering shop is selling a burner that might be usable. You could likely negotiate a fairer price than I could! The shop is just across the street. I'll make a note on your map for you.",questType="standard"},
[39346] = {id=39346,name="Testing the Calibration",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,mapID=627,description="Now that you have the burettes calibrated, it's time to test them out! The only way to be sure is by crafting a sufficient quantity of a variety of potions. Glamorous work? No, but the most important reagent in alchemy is a bit of elbow grease!",questType="standard"},
