[39869] = {id=39869,name="Toll for the Soul",level=10,requiredLevel=10,faction="none",expansion=6,zoneID=7812,mapID=634,description="As foretold, you have arrived... Helya is foolish to think I'll let her ferry me into Helheim. Odyn has already smiled upon me, my soul belongs in Valhallas. Make no mistake, I am not a prisoner. Before my death Odyn appeared to me in the form of a raven. He praised my battles in life and gave me a quest no vrykul could refuse. The Helerjar arrived... and I let them slay me. Prisoner-- nay, I am a liberator, sent by Odyn to free the souls of Valarjar.",questType="dungeon"},
[39942] = {id=39942,name="Aethrem Crystal",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Professor Pallin would be interested in seeing this.>",questType="standard"},
