[39962] = {id=39962,name="Trouble for Okuna",level=10,requiredLevel=10,faction="none",expansion=6,zoneID=8040,mapID=630,description="Help! I need somebody... but not just anybody. I need a champion! I finally escaped the grasp of Prince Oceanus only to be hunted by his father, King Deepbeard. I was enjoying my freedom and decided to go fishing when that giant attacked. I've been running around these islands trying to avoid that creature ever since... if anyone gets this message, please send help!",questType="dungeon"},
