[39989] = {id=39989,name="Keepers of the Hammer",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,description="High Chieftain Ulan has requested your presence. We have learned that the Burning Legion has returned and know that if you are true in your purpose in facing this evil, you will need our aid. Our people have in our possession a great titan relic: the Hammer of Khaz'goroth. We intend to lend it to you for this task. When you are ready, join me at our stronghold of Thunder Totem in Highmountain .",questType="standard"},
[39991] = {id=39991,name="Blessing of Cenarius",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
