[40013] = {id=40013,name="Aethril Sample",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="This herb has clearly been absorbing magical energy from the land. Filaments of ley energy course from root to leaf. Your herbalism trainer in Dalaran will want to see this.",questType="standard"},
[40015] = {id=40015,name="Ragged Strips of Silk",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Finely made strips of clothing, torn, tattered, and dirty: telltale signs of the withered. The feral, degenerate outcasts of nightborne society must also be harvesting the aethril... but why?",questType="standard"},
[40017] = {id=40017,name="A Slip of the Hand",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="As you harvest the aethril, your hand brushes the flower's pollinating organs against one another, creating a reaction. You may have discovered a new herbalism technique. Your trainer in Dalaran would be a good person to discuss this with.",questType="standard"},
[40018] = {id=40018,name="Dreamleaf Sample",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="The herb is brilliantly green, paper-thin, and somewhat sticky. Your herbalism trainer in Dalaran will want to see this.",questType="standard"},
[40024] = {id=40024,name="Foxflower Sample",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Something about this herb catches your eye... and your nose. Your herbalism trainer in Dalaran would certainly be interested in studying some samples of this piquant new flower.",questType="standard"},
[40025] = {id=40025,name="Teeny Bite Marks",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="This herb has been chewed by some of the local wildlife. What kind of animal would eat foxflower? A bear? Perhaps your trainer in Dalaran will know.",questType="standard"},
[40028] = {id=40028,name="The Pied Picker",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="As you finish gathering the foxflower, a particular part of the bloom catches your eye. One of the leaves has a small protuberance, right where it meets the stem. Further investigation suggests that this is where the foxflower's unusual smell comes from. Your herbalism trainer would be interested in seeing this.",questType="standard"},
[40029] = {id=40029,name="Fjarnskaggl Sample",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="To one not trained in herbalism, this brambly bush might appear to be entirely useless. Your training, however, reveals this to be a very special plant indeed. Your herbalism trainer in Dalaran will want to see some more samples of this.",questType="standard"},
[40030] = {id=40030,name="Ram's-Horn Trowel",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="The rune markings along the tool's grip suggest that it was left behind by a vrykul herbalist. Apparently, the vrykul are also gathering this fjarnskaggl. Your trainer, Kuhuine, mentioned that she had read about this herb in the past. Perhaps she might be interested in seeing the tools that the vrykul use to harvest it.",questType="standard"},
[40032] = {id=40032,name="The Missing Page",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="\"...the Cairn of the Sea, a place long-known to be beloved by the gods. He placed his offering of fjarnskaggl at the foot of the cairn, mouthed the words 'Herbs beget herbs', and received the blessing he desired.\" This may be related to the books you brought back to your herbalism trainer.",questType="standard"},
[40034] = {id=40034,name="Starlight Rosedust",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Despite all your training, the rose disintegrated in your hand. Your herbalism trainer in Dalaran will want to see this.",questType="standard"},
[40036] = {id=40036,name="Jeweled Spade Handle",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="An immaculately carved spade handle lies beside the rose. Apparently the spade was more beautiful than it was durable, as the blade has completely fallen off. Your herbalism trainer may be interested in seeing this.",questType="standard"},
[40038] = {id=40038,name="Insane Ramblings",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Scribbled, angry phrases on a dirty scrap of vellum. One part catches your eye: \"thinks knows how to gather herbs steal my blade slit THROAT when I just need a bit more mana maybe aethril, yes...\" Your herbalism trainer may be interested in seeing this.",questType="standard"},
[40040] = {id=40040,name="Felwort Sample",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="This herb bubbles and seethes with a foul energy. It is smooth, dry, and cool, yet somehow quite painful to touch. Your herbalism trainer in Dalaran will want to see this.",questType="standard"},
[40062] = {id=40062,name="Bulging Nightmare Pod",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Professor Pallin would be interested in seeing this.>",questType="standard"},
[40064] = {id=40064,name="Woody Seed Cluster",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Professor Pallin would be interested in seeing this.>",questType="standard"},
