[40112] = {id=40112,name="Huln's War - Malorne's Favored",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7838,mapID=697,description="Shan'do ask for you. Sent Eche'ro beast with message on rack. Unng Ak hear Eche'ro sound fighting. You find beast? Give help, maybe feathered night elf be relieve.",starts={{npcID=97891,x=0.294,y=0.392,mapID=697}},ends={{npcID=98794,x=0.28,y=0.472,mapID=697}},coords={x=0.294,y=0.392,source="quest_giver",mapID=697},questType="standard"},
