[40131] = {id=40131,name="Stonehide Leather Sample",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="The quality of this leather scrap appears representative of the beast hides found in the Broken Isles. Your skinning trainer in Dalaran would be interested in seeing this.",questType="standard"},
[40136] = {id=40136,name="Immaculate Stonehide Leather",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="You have been skinning for a long time now, but never have you seen a leather specimen as fine as this. Durable, pliable, beautifully colored... Your trainer in Dalaran would be VERY interested in seeing this.",questType="standard"},
[40141] = {id=40141,name="Stormscale Sample",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="This scale shimmers with electrical energy. Your skinning trainer in Dalaran would be interested in seeing this.",questType="standard"},
[40143] = {id=40143,name="Unfinished Treatise on the Properties of Stormscale",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Tucked between the folds of this animal's hide, you find a scrap of paper. It appears to be a handwritten guide to harvesting stormscales, but too much of the manuscript has been lost to be of use. Perhaps your skinning trainer in Dalaran could help you find its owner.",questType="standard"},
[40151] = {id=40151,name="Immaculate Stormscale",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="You have been skinning for a long time now, but never have you seen a scale specimen as fine as this. Your trainer in Dalaran would be VERY interested in seeing this.",questType="standard"},
[40156] = {id=40156,name="Felhide Sample",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,mapID=627,description="This demonic hide is completely unlike any standard beast hide you are accustomed to. Your skinning trainer in Dalaran would be interested in seeing this.",questType="standard"},
[40160] = {id=40160,name="Magic Clams",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="What are murlocs doing with arcane clams? Perhaps your Nightfallen allies could make use of them.",questType="standard"},
[40161] = {id=40161,name="Tapping the Underground",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="Have you seen them, ? These are not ordinary murlocs. They have been drawn by the ley line that flows from Azsuna into this land. Somehow they have managed to tap into its arcane current and are tapping its power for their own devious purposes. These disturbances must be stopped if the ley line is to remain intact.",questType="standard"},
[40162] = {id=40162,name="Snowblind Mesa Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40163] = {id=40163,name="Snowblind Mesa Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40164] = {id=40164,name="REUSE",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40166] = {id=40166,name="Leying with Murlocs",level=10,requiredLevel=10,faction="none",expansion=6,zoneID=7541,mapID=634,description="I have seen these Seerspine summon minor elementals, which is no small feat for a murloc, but their high summoner, Blargrrrl, is trying to summon Torretus from the river. I doubt a mere murloc has the capabilities to control an entity as powerful as Torrentus. Blargrrrl will be deeply entranced if he is trying such a feat. We'll need something powerful to halt his ritual. Infuse yourself with ley energies and return to me.",questType="standard"},
[40173] = {id=40173,name="The Unstable Prism",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=4395,mapID=118,description="As the prism struggles to stabilize in a single time flow, it bleeds a shadowy chill, the likes of which you haven't felt since Northrend. Surely some mage in Dalaran would be interested in this relic.",questType="standard"},
