[40335] = {id=40335,name="Sashj'tar Accord DISABLED",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,description="As far as you can decipher, the naga are recruiting the sea giants on behalf of Queen Azshara.>",questType="standard"},
[40342] = {id=40342,name="Surprise the Sashj'tar",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="The naga are preoccupied with recruiting the sea giants for Queen Azshara's battles in other lands. Now is the time to strike!",questType="standard"},
[40346] = {id=40346,name="Pilfered Provisions",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="The sea giants are sifting through the shipwrecks looking for treasure. Anything of value that can be found would be better off in the hands of the vrykul.",questType="standard"},
