[40604] = {id=40604,name="Disturbing the Past",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=41,mapID=42,description="This place is where the merchant, Ariden, set up camp while he was trying to ply his dubious wares to the sorcerer Medivh. It has remained strangely untouched for all this time, which leads me to believe it may still have a connection to its former owner. Help me search the camp. Let's see if we can find something to lead us to the Dark Riders.",starts={{npcID=100729,x=0.524,y=0.344,mapID=42}},ends={{npcID=245793,x=0.523,y=0.34,mapID=42}},coords={x=0.524,y=0.344,source="quest_giver",mapID=42},questType="standard"},
[40631] = {id=40631,name="Basking in Glory",level=45,requiredLevel=45,faction="none",expansion=6,description="You... you glow with the radiance of Odyn himself... You must return to your people at once. Odyn's light is a gift that must be shared with all.",questType="standard"},
[40635] = {id=40635,name="Sashj'tar Slayer",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="I cannot believe that Throndyr is gone. By the horns on my head, we shall have revenge for all of the pain that the Sashj'tar have inflicted on us! Press forward, . Kill them! Kill them all!",questType="standard"},
[40637] = {id=40637,name="Proof of Honor",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="This cave will be my final resting place, . Find Toryl. Tell her of what happened here today. Tell all of Jandvik that I died defending our village...",questType="standard"},
[40650] = {id=40650,name="Champion: Zen'tabra",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7846,mapID=747,starts={{npcID=98013,x=0.472,y=0.076,mapID=747}},ends={{npcID=98013,x=0.472,y=0.076,mapID=747}},coords={x=0.472,y=0.076,source="quest_giver",mapID=747},questType="standard"},
[40658] = {id=40658,name="Tracking Quest - W1 - See Demon Attack",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=14,mapID=1,questType="standard"},
[40659] = {id=40659,name="Seeing Stars",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="You think those naga are good sport, little rabbit? I would savor the chance to do battle with one of those barnacle-crusted behemoths. If you want to impress me, bring me the stars from their heads. I might consider you a true then.",questType="standard"},
[40674] = {id=40674,name="Jars for Jandvik",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="Last time we met, , I was in a cage. You risked your life once before for my kin. Are you willing to aid me once again? The serpents' attack has left many of us wounded. I require mending waters to perform my healing rituals. I have seen the serpents use this water. Return any that you find to me.",questType="standard"},
[40676] = {id=40676,name="You Must Make Haste",level=45,requiredLevel=45,faction="none",expansion=6,description="I suggest that you set off immediately, . You have been here for far too long - the Legion's assassins could close in at any moment to make an attempt on your life. Do take caution when using the heart - even with the bindings to aid you the power within is dangerous.",questType="standard"},
[40681] = {id=40681,name="Snarf",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40685] = {id=40685,name="Into the Mouth of the Nether",level=1,requiredLevel=1,faction="both",expansion=6,description="With the ritual failed and the council scattered, you find yourself trapped in the prison of the pit lord, Jagganoth. The situation is grim, but with the help of the remaining council members, you may be able to escape.",questType="standard"},
