[40713] = {id=40713,name="The Black Tome",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,mapID=680,description="I have made a great discovery, . There is a powerful warlock in the Soul Engine, in possession of a powerful tome. It contains forbidden secrets to summoning the most powerful of demons. Even the Legion is afraid to call on these fel lords, but now I possess knowledge beyond theirs. Fetch me the tome and I will never want for magic again.",starts={{npcID=101076,x=0.268,y=0.708,mapID=680}},ends={{npcID=101076,x=0.268,y=0.708,mapID=680}},coords={x=0.268,y=0.708,source="quest_giver",mapID=680},questType="standard"},
[40714] = {id=40714,name="The Call To War",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Hear me, . The Legion has returned. They hope to control us, to bend us to their will. Fools - they only walk back within reach of our blades. Your brethren within Dalaran have begun to gather at Krasus' Landing. Go, meet with Duke Lankral and all will be explained.",questType="standard"},
[40725] = {id=40725,name="Arganax",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,description="A satyr known as Arganax has infiltrated the village of Lorlathil in Val'sharah. I believe that Arganax has disguised himself as one of the local residents. Use the demon Eye of Azzorok on the villagers in Lorlathil. If there is a demon disguised as a local, the Eye of Azzorok will reveal their true identity. Uncover the demon infiltrator Arganax , and slay him without mercy.",questType="standard"},
[40749] = {id=40749,name="A Token of Remembrance",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="The flower rests peacefully in your hand, glowing softly. While it doesn't appear to be growing anywhere nearby, there are small bouquets of the flower on some of the memorials around here. Perhaps laying down some flowers on the remaining graves will ease the gloom.",questType="standard"},
