[40773] = {id=40773,name="Bloodshard",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40776] = {id=40776,name="Kazok'thul",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,description="A rogue felhunter known as Kazok'thul has been terrorizing Azurewing Repose in Azsuna. Felhunters feed on arcane energy and it seems that Kazok'thul has been gorging itself on the mana from nearby Azurewing whelps. Travel to Azurewing Repose and speak with Ardonu to find the last known location of Kazok'thul . Slay the demon and return here when your mission is complete.",questType="standard"},
[40779] = {id=40779,name="We Need Even More Power!",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="Good new, ! I have located another power orb. I last saw it down by the Nightborne encampment to the southwest. I had to get out of there before their patrols saw me, but it should be no trouble for you, now should it?",questType="standard"},
