[40905] = {id=40905,name="Lieutenant Strathmar",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[40906] = {id=40906,name="Serpents from the Deep",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="Hail, . My village of Jandvik has fallen under siege by a group of naga called the Sashj'tar. Normally I would not seek out the help of an outsider, but we are facing an enemy that we are incapable of defeating. Many powerful elven relics can be found in the ruins around Jandvik. In exchange for your help, you will have your just rewards. Do we have an accord?",questType="standard"},
[40921] = {id=40921,name="Tracking Quest: Bastillax 1",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
