[40941] = {id=40941,name="Missive: Assault on the Pit",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=7004,mapID=525,description="The Blackrock forces based out of the Pit in Gorgrond make up the bulk of the Iron Horde army. If we crush them on their home soil, the rest of the Iron Horde will have little hope of standing against us. If you choose the battle, bring friends. The Blackrock won't be defeated easily.",ends={{npcID=78495,x=0.408,y=0.518,mapID=525}},questType="group"},
[40943] = {id=40943,name="Missive: Assault on the Heart of Shattrath",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=7004,mapID=525,description="Sargerei forces from deep in Shattrath have grown stronger and bolder by the day. We can no longer risk ignoring the threat that they pose. Bring allies if you wish to face the Sargerei so deep within the city.",ends={{npcID=78495,x=0.408,y=0.518,mapID=525}},questType="group"},
[40957] = {id=40957,name="A Strong Right Hand",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7877,mapID=739,starts={{npcID=107317,x=0.434,y=0.258,mapID=739}},ends={{npcID=107317,x=0.434,y=0.258,mapID=739}},coords={x=0.434,y=0.258,source="quest_giver",mapID=739},questType="standard"},
[40960] = {id=40960,name="Luminous Pearl",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Balanced upon your fishing hook, you find a pearl unlike any other you've seen before. It shines with a cold, steady light, and its size and weight fluctuate in your hand. This is clearly a magical item, and should be brought to a magical person.",questType="standard"},
[40973] = {id=40973,name="Creating Time",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[40974] = {id=40974,name="Latosius' Trial",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="I bow to Latosius' wisdom. If we are to endure, it must be you who claims the Amulet. Survive this challenge, , and the might of the Moon Guard will be yours forevermore.",questType="standard"},
[40975] = {id=40975,name="Arluin Bribe Tracking",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[41000] = {id=41000,name="King Forgalash's Burden",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="That sea witch spoke the truth. I witnessed the Tidemistress confer with King Forgalash on several occasions. Kill Forgalash and bring the prow from his shoulder to Fjolrik as proof of his demise. I will meet afterwards in the center of Jandvik. I need to warm myself by its fires.",questType="standard"},
[41006] = {id=41006,name="Assassinate That Guy",level=10,requiredLevel=10,faction="none",expansion=6,zoneID=7502,mapID=627,questType="standard"},
[41008] = {id=41008,name="Hunter to Hunter",level=10,requiredLevel=10,faction="none",expansion=6,description="I sense the threads of fate entwined about you. Your destiny is tied to that of the ancient night elf who started you on this journey. I can send you back to the city in the sky. From there, you must begin the task of gathering allies against the ravenous darkness. Fight well, . May Talonclaw serve you well.",questType="standard"},
[41016] = {id=41016,name="BC TL",level=7,requiredLevel=7,faction="both",expansion=6,questType="standard"},
[41027] = {id=41027,name="One Last Breath",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="To whomever finds this note first, Before I was cast from Suramar , I was a master alchemist. In my time, I have concocted many potions and elixirs for the benefit of the Nightborne. All of this was forgotten when the Legion came. Before I succumb to the hunger, I wanted to create one last draught to celebrate my love of sea. Drink it and explore the vast deep in my honor.",questType="standard"},
[41031] = {id=41031,name="For the People",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[41034] = {id=41034,name="Testing the Waters",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,mapID=680,description="There is no place that the Sashj'tar can hide from you now, . They will not be expecting a direct attack in their waters. This is a perfect opportunity to cut down their commanders. Meet me in Jandvik after you have slaughtered them.",ends={{npcID=102845,x=0.706,y=0.492,mapID=680}},questType="standard"},
[41041] = {id=41041,name="Sashj'tar Allies DISBALED",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,description="Commander Malt'his was conferring with a sea giant? We are prepared to battle the naga, but if they have yoked the strength of the sea giants, we will have to double our efforts to save Jandvik. You must tell Toryl about this grave news right away.",questType="standard"},
