[41137] = {id=41137,name="Fall of the King",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="All that remains is the Sea Giant King. Place our banner upon his beach and draw him out of the sea. Once he has revealed himself, use the trident to wound him. There is a derelict boat that washed up on the shore. Use that to quickly get to the king's island. Gird your loins, . This fight will not be easy.",questType="standard"},
[41195] = {id=41195,name="Culling Ambervale",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[41226] = {id=41226,name="Breaking Out",level=1,requiredLevel=1,faction="both",expansion=6,description="We cannot fight our way out of the Vault alone. Two of your allies, Kayn Sunfury and Altruis the Sufferer, are imprisoned within this room. Free them with haste. Their strength will be of great use to us.",questType="standard"},
