[41367] = {id=41367,name="Priority Delivery",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7695,mapID=648,description="An adventurer of another time has forgotten to loot something big... something that might cause them great emotional strain if not received quickly. Your destination is Icecrown Citadel, your target the Lich King's corpse. Retrieve the missing item post-haste and deliver it to the stalwart adventurer - he should be somewhere at the Steam Pools in Feralas. My assistant will open a portal to deliver you there. Just a moment!",ends={{npcID=52562,x=0.686,y=0.73,mapID=69}},questType="standard"},
