[41774] = {id=41774,name="The Rival Lords of Fire",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=8125,mapID=738,description="You stand before the true Lord of the Firelands, mortal. This land is mine by right, claimed from the ashes of Ragnaros himself. However, there are still some who foolishly oppose my reign. I would take great pleasure in destroying their worthless souls, but I will not honor them with death by my hands. They must be humiliated for their insolence, and there is nothing more humiliating than being slain by a mere mortal. Amuse me shaman. Prove your worth and destroy my rivals!",questType="standard"},
