[41981] = {id=41981,name="Traversing the Heavens",level=10,requiredLevel=10,faction="none",expansion=6,description="If you are not opposed, , I would accompany you on your journey through Skywall. There are wonders here that my eyes have never before beheld, and it would be my great honor to join you. Our quest to resurrect the mighty Thunderaan and unite the four great elemental lords will be no easy task. Lead the way, Farseer, and I shall follow.",questType="standard"},
