[41989] = {id=41989,name="Blood of My Blood",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,mapID=680,description="As my darling has demonstrated, Elisande's decision to bring down the shield has sown unrest among the nightborne. Loyalists and demons march together in the streets. Fear and distrust grip our hearts. Family turns against family. I will help Thalyssra stir a new rebellion, but first we must deal with Anarys. I do not wish to spill the blood of my blood - only to help see reason. Anarys is likely brooding over our father's memorial. Bring to me alive.",starts={{npcID=105342,x=0.434,y=0.788,mapID=680}},ends={{npcID=105342,x=0.434,y=0.788,mapID=680}},coords={x=0.434,y=0.788,source="quest_giver",mapID=680},questType="standard"},
[41991] = {id=41991,name="Rescue Efforts",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[41994] = {id=41994,name="Legion Portal",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[41997] = {id=41997,name="A Strong Defense",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[42003] = {id=42003,name="Kept Secret, Kept Safe",level=1,requiredLevel=1,faction="both",expansion=6,description="With the scrolls in hand, now you must set to the task of finding the staff. When Aegwynn relinquished it many years ago, it was entrusted to Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away from the hands of men. Only they would know exactly where it was taken, or how to retrieve it. The dragon Kalec may be our best chance. He now resides upon the Council of Six in Dalaran. Seek him, and your answers, there.",questType="standard"},
[42010] = {id=42010,name="Arcane Unleashed",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=7502,mapID=627,description="You have the power you need to destroy the Surge Needles. At the location of the breaches where the Surge Needles pierce the ground, there will be a large concentration of void energy. Focus the power of Aluneth into these points. The reaction should cause an overload, destroying the Surge Needle above. You must act quickly. The Ethereum won't sit idly by as you lay waste to their machinations.",questType="standard"},
