[42052] = {id=42052,name="The Shade of Xavius",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7673,mapID=641,description="Brightwing loves nice things - rainbows, unicorns, and flowers! But enemies, Brightwing does not forget. Brightwing remembers for a long, long time those that hurt the grove. Now, we must destroy our enemies... so that the grove can be nice and happy forever! Friend, go to Darkheart Thicket beneath the roots of Shaladrassil. There, find the one named Xavius... the one who started it all. Kill him, and bring me his head.",questType="dungeon"},
