[42377] = {id=42377,name="The Brother's Trail",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="We must reclaim the Silver Hand before those with evil intent can seize it. To free it from its wards, we need relics called the Sparks of Tyr. I have one, as does my brother, Galford. He journeyed to Northrend to seek aid from the Tyr's homeland, but has not returned. I must ask you to find him, and his Spark.",questType="standard"},
