[42435] = {id=42435,name="Prepare To Be Assimilated",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,mapID=630,description="The Empyrean Society is a dangerous cult. They claim to study all magic regardless of its source, but in reality they focus mostly on the forbidden. They will welcome you to their enclave if you bring them a magical artifact. The Hatecoil naga have found the perfect gifts - a Pearl of Arcane Wisdom and scrolls from the depths beneath the Nar'thalas Academy. You will have to convince them to part with a few. I will meet you on the road just north of the Empyrean Enclave.",starts={{npcID=107532,x=0.648,y=0.378,mapID=630}},ends={{npcID=106530,x=0.66,y=0.324,mapID=630}},coords={x=0.648,y=0.378,source="quest_giver",mapID=630},questType="standard"},
