[42753] = {id=42753,name="Vault of the Wardens: Vault Break-In",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8022,mapID=720,description="The Wardens made good on the deal. All that's left is to travel to the Isle of the Watchers off of southwest Azsuna. There, you'll need to break back in to the Vault of the Wardens and descend down into its lowest recesses where we were once imprisoned. Within the so-called Vault of the Betrayer, where the Wardens once held the Master's corpse, you'll find Sargerite Keystone . Good luck, .",questType="dungeon"},
