[43550] = {id=43550,name="Court of Stars: Into the Court of Stars",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=8079,mapID=680,description="The weather is perfect for a party, isn't it? Travel to the Court of Stars , where the Grand Magistrix herself may appear among her nobles to reassure them of the need for all the Legion patrols.",questType="dungeon"},
[43552] = {id=43552,name="Eye of Azshara: Into the Eye of Azshara",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7834,mapID=702,description="Our investigation found that the naga, under the orders of Queen Azshara herself, are preparing to summon a powerful entity to unleash Azshara's power across the Broken Isles. Travel to the Eye of Azshara , and put a stop to the ritual.",ends={{npcID=99179,x=0.528,y=0.596,mapID=709},{npcID=106199,x=0.666,y=0.46,mapID=717}},questType="dungeon"},
[43555] = {id=43555,name="The Arcway: Into the Arcway",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7855,mapID=680,description="The Arcway is even more vast than we thought, and holds many dangers. If we have any hope of taking the city, we must first see to the underground. Enter The Arcway and clear out any, and all enemies.",questType="dungeon"},
[43557] = {id=43557,name="Assault on Violet Hold: Into the Violet Hold",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=8022,mapID=720,description="The Violet Hold contains some of the Lich King's most powerful servants, and is at risk of being overrun by Legion agents. We must go there and thwart the demons before any of the prisoners can be set free.",questType="dungeon"},
[43561] = {id=43561,name="I Believe I Can Fly!",level=10,requiredLevel=10,faction="none",expansion=6,zoneID=7334,mapID=630,description="Let's not bother explaining how this happened, just know that I have the plan of all plans to escape this... this... This place stinks! But you can help! These feathers here will help craft my escape plan. If you wouldn't mind, I'm sure there's enough for the both of us!",questType="standard"},
