[44083] = {id=44083,name="The Grimoire of the First Necrolyte",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=41,mapID=42,description="This ancient tome appears to be the spellbook of Sataiel, the first necrolyte. Within its pages of curses and cantrips, you discover instructions for a ritual that Sataiel was concocting to empower Ulthalesh, the Deadwind Harvester. She calls this ritual, \"The Rite of the Executioner.\" The site was chosen and prepared, but Sataiel met her unfortunate end before she could proceed. Perhaps you can pick up where she left off? First, you'll need some skulls.",ends={{npcID=254007,x=0.386,y=0.74,mapID=42}},questType="standard"},
