[44482] = {id=44482,name="Recruiting Ebon Knights",level=10,requiredLevel=10,faction="none",expansion=6,description="Korgaz Deadaxe has been hard at work training a new generation of death knights. He has done an excellent job culling the ranks of weakness. Those who have survived the trials of death knight training are ready to join the ranks of the Ebon Blade. Korgaz is waiting for you on the upper level. I suggest you speak with him at your soonest convenience. New death knights will bolster our ranks and aid is in the war against the Burning Legion.",questType="standard"},
