[44557] = {id=44557,name="Finite Numbers",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=41,mapID=42,description="It seems not all the protections I put in place have been defeated. The Legion isn't able to open portals inside or near the tower... at least, not yet. They appear to be bringing reinforcements in through the catacombs running beneath Deadwind Pass . Disable them and you just might buy us the time we need to drive them out of Karazhan.",questType="group"},
