[44578] = {id=44578,name="Honor the Flame",level=1,requiredLevel=1,faction="none",expansion=6,description="The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, ?",questType="standard"},
