[45102] = {id=45102,name="Begin the Assault",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=8581,description="The battle for our world has been hard fought, but with the power of your weapon and the combined forces of Azeroth, we have driven the demon invaders back at every turn. Now we stand once again upon the Broken Shore, poised to do that which we previously failed to accomplish. Let us not forget those who sacrificed everything to give us this chance. Our first objective is to take the hill before us, so that we may build a stronghold. Steel yourself, . The assault on the Broken Shore begins now.",questType="standard"},
