[45159] = {id=45159,name="Cubic Conundrum",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,mapID=627,description="mysterious cube . Its design is unfamiliar, but unmistakably ancient. The cube's surface is inlaid with magical runes. Though inert, its properties may be worth investigating. Perhaps if you show it to Dariness the Learned in Dalaran , she could tell you more about it.>",questType="standard"},
[45167] = {id=45167,name="REUSE ME",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7588,mapID=649,description=", we will need to bolster our army by any means necessary to have any hope of driving back the legion. The kvaldir are cursed beyond redemption, but they are fierce warriors and are a resource we should not overlook. They are bound to obey whomever posesses Helya's Horn . You must obtain it. Her so-called helarjar were tasked with guarding it. You will have to take it from them.",questType="standard"},
[45170] = {id=45170,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=10,mapID=47,questType="standard"},
[45179] = {id=45179,name="Win the Crowd",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7834,mapID=702,description="The letter invites you to fight in one of the greatest events in the history of Azeroth. The grand arena battles, where fighters win glory and honor, and everyone will remember their names. Or at least until the next season.",ends={{npcID=96746,x=0.33,y=0.6,mapID=726},{npcID=98002,x=0.528,y=0.514,mapID=747},{npcID=99179,x=0.528,y=0.596,mapID=709},{npcID=103023,x=0.43,y=0.468,mapID=739},{npcID=106199,x=0.666,y=0.46,mapID=717}},questType="standard"},
[45182] = {id=45182,name="Frost: The Twisted Twin",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=7543,mapID=646,description="I have a request from an old friend, Karam Magespear , to help find his brother, Raest. Karam fears that Raest is dealing with dark powers, and wishes to stop him. Originally Raest trained with the Kirin Tor, but such were his aspirations of power that he turned to the forbidden art of Necromancy. He was discovered and expelled from our order. Find Karam in the Legerdemain Lounge and see if you can lend a hand. Specialization: Frost Mage",ends={{npcID=116175,x=0.564,y=0.272,mapID=646}},questType="standard"},
