[45441] = {id=45441,name="Adacic Grubs - REWORK",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7543,mapID=646,description="Your request to harvest wood does not seem unreasonable, . There is something you can do for me, too. There is a species of moth whose grubs feed on trees. Normally their numbers are too low to cause damage, but once a century they reproduce in overwhelming numbers. They have just begun their mass emergence. All of my keepers are fighting the nightmare and cannot be spared. I fear I am unable to protect the forest giants on my own. Will you stomp the grubs out?",questType="standard"},
