[45534] = {id=45534,name="A Common Enemy",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,mapID=627,description="I have one more request to ask of you, outsider. Return to your leaders and report to them what transpired here. Though your people may never truly be allies with the Tideskorn, know that we have a common enemy - one which my people will fight to the last vrykul. When the time comes, I hope to see you on the battlefield.",questType="standard"},
[45577] = {id=45577,name="thing",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7543,mapID=646,questType="standard"},
[45627] = {id=45627,name="Feltotem's Fall",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=7502,mapID=627,description="Our Highmountain contact, Navarrogg, reports that Tugar Bloodtotem has finally resurfaced. He's sent a message crystal along with some instructions for me. I can teleport you to Navarrogg and he will take you to Tugar's location, but there is one problem. Navarrogg requires additional magical power to fend off Tugar's fel magicks. You will need some Nethershards before you go.",starts={{npcID=117871,x=0.456,y=0.622,mapID=646}},coords={x=0.456,y=0.622,source="quest_giver",mapID=627},questType="standard"},
[45631] = {id=45631,name="Avocation of Antonidas",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=267,mapID=25,description="Archmage, I've found something you may be interested in. An old journal of the late Archmage, Antonidas. In it, he speaks of a project he was working on that I think we may be able to finish. It was a sort of flying disc that could attune itself to the rider's magical attunement. But I need your help tracking down the pieces. From what I could gather, he gave them to trusted friends and allies through the years. Perhaps you could persuade them to give us the pieces.",questType="standard"},
[45766] = {id=45766,name="Albino Elderhorn",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
