[45864] = {id=45864,name="A Gift From the Six",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=7502,mapID=627,description=", without you some of the Legion's strongest agents would still be roaming Azeroth, threatening to undermine all that we've accomplished in this war. Such a deed merits more than mere recognition. If you would accept it, we would like to formally reward your heroism in the face of such darkness with a portion of our power.",questType="standard"},
[45873] = {id=45873,name="Champion: Eitrigg",level=45,requiredLevel=45,faction="horde",expansion=6,zoneID=7813,mapID=695,questType="standard"},
