[45915] = {id=45915,name="The Folly of Levia Laurance",level=45,requiredLevel=45,faction="none",expansion=6,description="Levia Laurance was once a member of the Kirin Tor, long ago, and a good friend. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good. Levia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous for all of us if her knowledge fell into their hands. She was last seen at the Militant Mystic. Ask around there and see if you can pick up her trail.",questType="standard"},
[45975] = {id=45975,name="Investigate the Broken Shore",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=139,mapID=23,description="All of us know the price we paid the last time we set foot upon the Broken Shore. I recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.",questType="standard"},
