[46127] = {id=46127,name="Thwarting the Twins",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=14032,mapID=2112,description="I have news from Archmage Karlain ! The Kirin Tor have found Raest Magespear and can open up a portal to his location! If you are ready to face him, I can have the mages here open the portal into the Twisting Nether.",starts={{npcID=117871,x=0.456,y=0.622,mapID=646}},coords={x=0.456,y=0.622,source="quest_giver",mapID=2112},questType="standard"},
[46128] = {id=46128,name="Time for a Recharge",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,mapID=627,questType="standard"},
[46151] = {id=46151,name="Furthering Knowledge",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=139,mapID=23,description="I am surprised and awed each day I delve deeper into the history of these weapons. Our researcher has been going extremely well and we have been busy preparing notes for you. With a few more resources I am sure we can prepare something to boost your artifact knowledge a little. Remember though, this is only a first step. These weapons have been around longer than most recorded history so much deeper knowledge will take time.",questType="standard"},
[46152] = {id=46152,name="Furthering Knowledge",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=8022,mapID=720,description="Through pain and blood we have cut through the initial layers of research. We have been busy preparing notes for you and with a few more resources we can get you something to boost your artifact knowledge. This is only the first step, more resources will be required to catch you up further.",questType="standard"},
[46154] = {id=46154,name="Furthering Knowledge",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7846,mapID=747,description="The amount of power in these artifacts is incredible and we have only scratched the surface. Our researchers have been busy preparing notes for you and with a few more resources I am sure they can prepare something to boost your artifact knowledge. This is only the first step, with more resources we should be able to help you catch up even more.",ends={{npcID=111737,x=0.34,y=0.322,mapID=747}},questType="standard"},
[46159] = {id=46159,name="An Urgent Message",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8022,mapID=720,description="We received an urgent message from one of Belath's scouts down on Mardum! I think you had better listen to it.",questType="standard"},
[46176] = {id=46176,name="The Archmage Accosted",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=16,mapID=76,description="With the barrier dispelled, Archmage Xylem is finally within reach! Hopefully he'll be cooperative in returning the Iris...",questType="standard"},
[46202] = {id=46202,name="Rare Elite 14",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7543,mapID=646,questType="standard"},
[46206] = {id=46206,name="Whispers of a Frightened World",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,mapID=627,description="\"Champion! Azeroth needs our help.\"",questType="standard"},
[46242] = {id=46242,name="The Dreadlord's Calling",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7543,mapID=646,description="According to the cultist, the leader you seek should be in her tower overseeing the operations in the Dark Stockades.",ends={{npcID=119166,x=0.354,y=0.382,mapID=717}},questType="standard"},
[46252] = {id=46252,name="Intolerable Infestation",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7543,mapID=646,description="While we purge Legion filth from the Broken Shore, the fiends maintain their hold on nearby lands. Their presence can no longer be tolerated. The fetid strongholds of Faronaar and Felsoul Hold infest Azsuna and Suramar. Choose an attack point and cut a swath through their insidious ranks. Return to me with demon blood on your hands, then we can resume our campaign to drive Kil'jaeden from the Tomb.",starts={{npcID=116576,x=0.446,y=0.634,mapID=646}},ends={{npcID=116576,x=0.446,y=0.634,mapID=646}},coords={x=0.446,y=0.634,source="quest_giver",mapID=646},questType="standard"},
